(7735507, 1275145, 141319, '<td valign="top">:-) I like these minimalist interpretations of challenges</td>', ':-) I like these minimalist interpretations of challenges', '2022-12-26 01:04:53.000000', NULL, 1),
(7735508, 1274965, 141319, '<td valign="top">Beautiful image.</td>', 'Beautiful image.', '2022-12-26 01:05:28.000000', NULL, 1),
