(7735747, 1275192, 30049, '<td valign="top">Clever capture.  Liking it.  Good luck.</td>', 'Clever capture.  Liking it.  Good luck.', '2022-12-29 20:44:20.000000', NULL, 1),
(7735748, 1275107, 30049, '<td valign="top">Cute take on the challenge (I think).  Having a hard time turning my laptop upside town to really take it in.  :-P  Good luck.</td>', 'Cute take on the challenge (I think).  Having a hard time turning my laptop upside town to really take it in.  :-P  Good luck.', '2022-12-29 20:45:33.000000', NULL, 1),
(7735749, 1275073, 30049, '<td valign="top">I''m usually a fan of negative space and I get what you''re trying to do here.  Guess it works in the literal sense of "on the edge".  There are other approaches to this challenge theme that I prefer a bit better.  Sorry.  Nothing personal.  Good luck.</td>', 'I''m usually a fan of negative space and I get what you''re trying to do here.  Guess it works in the literal sense of "on the edge".  There are other approaches to this challenge theme that I prefer a bit better.  Sorry.  Nothing personal.  Good luck.', '2022-12-29 20:51:21.000000', NULL, 1),
